const WIDTHS =
  "";

function widthAt(index: number) {
  if (index === 106) return "2331112";
  return WIDTHS.slice(index * 6, index * 6 + 6);
}

export function code128Bars(value: string) {
  if (!/^[0-9A-Z]+$/.test(value)) return [];
  const codes = [104];
  let sum = 104;
  for (let i = 0; i < value.length; i += 1) {
    const code = value.charCodeAt(i) - 32;
    if (code < 0 || code > 94) return [];
    codes.push(code);
    sum += code * (i + 1);
  }
  codes.push(sum % 103, 106);
  const bars: { x: number; w: number; black: boolean }[] = [];
  let x = 10;
  for (const code of codes) {
    const pattern = widthAt(code);
    for (let i = 0; i < pattern.length; i += 1) {
      const w = Number(pattern[i]);
      bars.push({ x, w, black: i % 2 === 0 });
      x += w;
    }
  }
  bars.push({ x, w: 10, black: false });
  return bars;
}
